-- 站内信：一位接收人对应一条记录，已读状态互不影响。
CREATE TABLE IF NOT EXISTS "sys_notification" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "recipient_id" bigint NOT NULL,
  "sender_id" bigint NULL,
  "type" varchar(32) NOT NULL DEFAULT 'SYSTEM',
  "title" varchar(255) NOT NULL,
  "content" varchar(5000) NOT NULL,
  "business_type" varchar(64) NULL,
  "business_id" varchar(100) NULL,
  "action_url" varchar(500) NULL,
  "read_status" smallint NOT NULL DEFAULT 0,
  "read_time" timestamp NULL,
  "status" smallint NOT NULL DEFAULT 1,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expire_time" timestamp NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "idx_sys_notification_recipient_unread" ON "sys_notification"
  ("recipient_id", "status", "read_status", "create_time" DESC);
CREATE INDEX IF NOT EXISTS "idx_sys_notification_recipient_page" ON "sys_notification"
  ("recipient_id", "status", "create_time" DESC);
CREATE INDEX IF NOT EXISTS "idx_sys_notification_business" ON "sys_notification"
  ("business_type", "business_id");

INSERT INTO "sys_menu"
  ("parent_id", "name", "path", "component", "type", "permission", "icon", "sort", "status", "create_time", "update_time")
SELECT 0, '我的消息', '/notification', 'notification/index', 1, NULL, 'Bell', 7, 1, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM "sys_menu" WHERE "path" = '/notification');

-- 个人收件箱对每个启用角色可见，实际数据仍由 recipient_id 严格隔离。
INSERT INTO "sys_role_menu" ("role_id", "menu_id")
SELECT r.id, m.id
FROM "sys_role" r
CROSS JOIN "sys_menu" m
WHERE r.status = 1
  AND m.path = '/notification'
  AND NOT EXISTS (
    SELECT 1 FROM "sys_role_menu" rm WHERE rm.role_id = r.id AND rm.menu_id = m.id
  );
